// How strong the evidence behind a card is
export type Evidence = "strong" | "moderate" | "mixed" | "myth" | "practical";

// The words shown for each evidence label (never colour alone)
export const EVIDENCE_LABELS: Readonly<Record<Evidence, string>> = {
  // Replicated, or a large review
  strong: "Strong evidence",
  // A good study or two
  moderate: "Moderate evidence",
  // Studies disagree
  mixed: "Mixed evidence",
  // Popular, but not supported
  myth: "A myth",
  // Practical advice, not a research finding
  practical: "Practical advice",
};

// The kinds of card
export type CardKind = "explainer" | "myth-or-fact" | "try-it";

// The sets of cards
export type LearnSetId = "nerves" | "charisma" | "body" | "conversation" | "warmth" | "stories" | "practice" | "voice" | "point" | "minds" | "hard" | "words" | "profile" | "humour" | "work" | "skills";

