// A number from one to twenty in words, as the cards write them (larger numbers stay as digits)
function inWords(count: number): string {
  // The words, by number
  const words = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen", "twenty"];
  // The word, or the digits
  return words[count] ?? String(count);
}

// What the "one take tells you little" card says about the profile, built from the profile's own rules so the two cannot drift apart (decision 94)
export const PROFILE_TRENDS_MEANING = `Your profile compares your “usual” (the middle of your first ${inWords(PROFILE_RULES.usualTakes)} takes) with your “recent” (the middle of your latest ${inWords(PROFILE_RULES.recentTakes)}), and calls a trend only after ${inWords(PROFILE_RULES.minForTrend)} takes.`;

// A myth-or-fact card's verdict
export type Verdict = "myth" | "fact" | "mixed";

// One card
export interface LearnCard {
  // Stable id
  id: string;
  // Its set
  set: LearnSetId;
  // Its kind
  kind: CardKind;
  // The question or belief it starts from, set like a headline
  title: string;
  // For a myth-or-fact card: the verdict the guess is checked against
  verdict?: Verdict;
  // What the research found, in two or three plain sentences
  finding: string;
  // What it means, in one or two lines
  meaning: string;
  // What to do, in one or two lines
  doThis: string;
  // For a try-it card: a short exercise to say aloud on the card
  exercise?: string;
  // The practice session that fits the card best, shown as the card's last step (every card has one; the table is in documents/plan-learn.md)
  tryIt: { label: string; href: string };
  // The one line to remember (shown again after a wrong recall, and used for saying it back)
  keyLine: string;
  // The recall question, with its options and the right one
  recall: { question: string; options: ReadonlyArray<string>; answer: number };
  // How strong the evidence is
  evidence: Evidence;
  // The source, in short form, and where to read it
  source: { text: string; url?: string };
  // A small step to try for real, away from the app (decision 71)
  outThere?: string;
  // A scenario to choose the best reply in, then say it aloud (ids from src/content/scenarios.ts)
  scenario?: string;
}

