// Find a card by id (a retired id finds the card that replaced it)
export function findCard(id: string): LearnCard | undefined {
  // The id to look for: the replacement's, for a retired card (an own key only, so "toString" and the like are not mistaken for one)
  const live = Object.hasOwn(RETIRED_CARDS, id) ? (RETIRED_CARDS[id] ?? id) : id;
  // Look it up
  return LEARN_CARDS.find((card) => card.id === live);
}
